1	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
2	import { instanceServiceClient } from "@/connect";
3	import { InstanceSetting, InstanceSetting_Key } from "@/types/proto/api/v1/instance_service_pb";
4	
5	// Query keys factory
6	export const instanceKeys = {
7	  all: ["instance"] as const,
8	  profile: () => [...instanceKeys.all, "profile"] as const,
9	  settings: () => [...instanceKeys.all, "settings"] as const,
10	  setting: (key: InstanceSetting_Key) => [...instanceKeys.settings(), key] as const,
11	  settingsBatch: (keys: InstanceSetting_Key[]) => [...instanceKeys.settings(), "batch", ...keys] as const,
12	  stats: () => [...instanceKeys.all, "stats"] as const,
13	};
14	
15	// Build setting name from key
16	const buildInstanceSettingName = (key: InstanceSetting_Key): string => {
17	  const keyName = InstanceSetting_Key[key];
18	  return `instance/settings/${keyName}`;
19	};
20	
21	// Hook to fetch instance resource statistics. Admin only on the server side.
22	export function useInstanceStats() {
23	  return useQuery({
24	    queryKey: instanceKeys.stats(),
25	    queryFn: () => instanceServiceClient.getInstanceStats({}),
26	    staleTime: 60_000, // 60s — matches server-side cache TTL
27	  });
28	}
29	
30	// Hook to fetch instance profile
31	export function useInstanceProfile() {
32	  return useQuery({
33	    queryKey: instanceKeys.profile(),
34	    queryFn: async () => {
35	      const profile = await instanceServiceClient.getInstanceProfile({});
36	      return profile;
37	    },
38	    staleTime: 1000 * 60 * 10, // 10 minutes - instance profile rarely changes
39	  });
40	}
41	
42	// Hook to fetch a specific instance setting
43	export function useInstanceSetting(key: InstanceSetting_Key) {
44	  return useQuery({
45	    queryKey: instanceKeys.setting(key),
46	    queryFn: async () => {
47	      const setting = await instanceServiceClient.getInstanceSetting({
48	        name: buildInstanceSettingName(key),
49	      });
50	      return setting;
51	    },
52	    staleTime: 1000 * 60 * 5, // 5 minutes
53	  });
54	}
55	
56	// Hook to fetch multiple instance settings
57	export function useInstanceSettings(keys: InstanceSetting_Key[]) {
58	  return useQuery({
59	    queryKey: instanceKeys.settingsBatch(keys),
60	    queryFn: async () => {
61	      const response = await instanceServiceClient.batchGetInstanceSettings({
62	        names: keys.map(buildInstanceSettingName),
63	      });
64	      return response.settings;
65	    },
66	    staleTime: 1000 * 60 * 5, // 5 minutes
67	  });
68	}
69	
70	// Hook to update instance setting
71	export function useUpdateInstanceSetting() {
72	  const queryClient = useQueryClient();
73	
74	  return useMutation({
75	    mutationFn: async (setting: InstanceSetting) => {
76	      await instanceServiceClient.updateInstanceSetting({ setting });
77	      return setting;
78	    },
79	    onSuccess: (setting) => {
80	      // Extract key from setting name and invalidate
81	      const keyMatch = setting.name.match(/instance\/settings\/(\w+)/);
82	      if (keyMatch) {
83	        const keyName = keyMatch[1] as keyof typeof InstanceSetting_Key;
84	        const key = InstanceSetting_Key[keyName];
85	        if (key !== undefined) {
86	          queryClient.setQueryData(instanceKeys.setting(key), setting);
87	        }
88	      }
89	      queryClient.invalidateQueries({ queryKey: instanceKeys.settings() });
90	    },
91	  });
92	}
93	
94	// Derived hooks for common settings
95	export function useGeneralSetting() {
96	  const { data: setting, ...rest } = useInstanceSetting(InstanceSetting_Key.GENERAL);
97	  const generalSetting = setting?.value.case === "generalSetting" ? setting.value.value : undefined;
98	  return { data: generalSetting, ...rest };
99	}
100	
101	export function useMemoRelatedSetting() {
102	  const { data: setting, ...rest } = useInstanceSetting(InstanceSetting_Key.MEMO_RELATED);
103	  const memoRelatedSetting = setting?.value.case === "memoRelatedSetting" ? setting.value.value : undefined;
104	  return { data: memoRelatedSetting, ...rest };
105	}
